package org.apache.commons.math.stat.inference;

import java.io.*;
import java.math.*;
import java.util.*;
import org.apache.commons.math.MathException;
import org.apache.commons.math.distribution.ChiSquaredDistribution;
import org.apache.commons.math.distribution.ChiSquaredDistributionImpl;
import org.apache.commons.math.distribution.DistributionFactory;
import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;

public class ChiSquareTestImpl_chiSquare_TriageGen0Test {

    private ChiSquareTestImpl testInstance;
    private static final double DELTA = 1e-10;

    @Before
    public void setUp() {
        testInstance = new ChiSquareTestImpl();
    }

    @Test
    public void testChiSquare_Success() {
        double[] expected = {10.0, 20.0, 30.0};
        long[] observed = {12L, 18L, 30L};

        // Calculation:
        // (12-10)^2 / 10 = 4 / 10 = 0.4
        // (18-20)^2 / 20 = 4 / 20 = 0.2
        // (30-30)^2 / 30 = 0 / 30 = 0.0
        // Total = 0.6
        double expectedResult = 0.6;
        double actualResult = testInstance.chiSquare(expected, observed);
        assertEquals(expectedResult, actualResult, DELTA);
    }

    @Test
    public void testChiSquare_ExpectedLengthTooSmall() {
        double[] expected = {10.0};
        long[] observed = {10L};
        try {
            testInstance.chiSquare(expected, observed);
            fail("Expected IllegalArgumentException due to expected.length < 2");
        } catch (IllegalArgumentException e) {
            assertEquals("observed, expected array lengths incorrect", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_LengthMismatch() {
        double[] expected = {10.0, 20.0};
        long[] observed = {10L, 20L, 30L};
        try {
            testInstance.chiSquare(expected, observed);
            fail("Expected IllegalArgumentException due to length mismatch");
        } catch (IllegalArgumentException e) {
            assertEquals("observed, expected array lengths incorrect", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ExpectedNotPositive_Zero() {
        double[] expected = {0.0, 10.0};
        long[] observed = {5L, 5L};
        try {
            testInstance.chiSquare(expected, observed);
            fail("Expected IllegalArgumentException due to expected containing zero");
        } catch (IllegalArgumentException e) {
            assertEquals("observed counts must be non-negative and expected counts must be postive", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ExpectedNotPositive_Negative() {
        double[] expected = {-1.0, 10.0};
        long[] observed = {5L, 5L};
        try {
            testInstance.chiSquare(expected, observed);
            fail("Expected IllegalArgumentException due to expected containing negative");
        } catch (IllegalArgumentException e) {
            assertEquals("observed counts must be non-negative and expected counts must be postive", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ObservedNotNonNegative_Negative() {
        double[] expected = {10.0, 10.0};
        long[] observed = {5L, -1L};
        try {
            testInstance.chiSquare(expected, observed);
            fail("Expected IllegalArgumentException due to observed containing negative");
        } catch (IllegalArgumentException e) {
            assertEquals("observed counts must be non-negative and expected counts must be postive", e.getMessage());
        }
    }

    @Test
    public void testChiSquare_ExactMatch() {
        double[] expected = {10.0, 20.0};
        long[] observed = {10L, 20L};
        assertEquals(0.0, testInstance.chiSquare(expected, observed), DELTA);
    }
}
